"use client";

import { useState } from "react";
import {
    Plus,
    Search,
    Filter,
    ArrowUpRight,
    ArrowDownRight,
    Package,
    AlertTriangle,
    History,
    Calendar,
    ChevronRight,
    Loader2
} from "lucide-react";
import { useData } from "@/lib/hooks";

export default function StockPage() {
    const [searchTerm, setSearchTerm] = useState("");
    const [filter, setFilter] = useState("all");

    const { data: stockItems, loading } = useData<any[]>("/api/products");

    const filteredItems = stockItems?.filter(item => {
        const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
        if (filter === "low") return matchesSearch && item.stock < 20;
        if (filter === "expiring") return matchesSearch && item.batches.some((b: any) => {
            const days = Math.ceil((new Date(b.expiryDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));
            return days < 60;
        });
        return matchesSearch;
    }) || [];

    const stats = {
        totalItems: stockItems?.length || 0,
        lowStock: stockItems?.filter(i => i.stock < 20).length || 0,
        outOfStock: stockItems?.filter(i => i.stock === 0).length || 0,
        expiringSoon: stockItems?.filter(i => i.batches.some((b: any) => {
            const days = Math.ceil((new Date(b.expiryDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));
            return days < 60;
        })).length || 0
    };

    if (loading) return <div className="flex justify-center py-12"><Loader2 className="h-10 w-10 text-purple-600 animate-spin" /></div>;

    return (
        <div className="flex flex-col gap-8 animate-fade-in-up">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 uppercase tracking-tight">Stock Core</h1>
                    <p className="text-gray-500 mt-1 font-medium">Real-time IR SOFTWARE inventory analytics.</p>
                </div>
            </div>

            {/* Stats Summary */}
            <div className="grid gap-6 md:grid-cols-4">
                {[
                    { label: "Total Items", value: stats.totalItems, icon: Package, color: "bg-blue-500" },
                    { label: "Low Stock", value: stats.lowStock, icon: AlertTriangle, color: "bg-orange-500" },
                    { label: "Out of Stock", value: stats.outOfStock, icon: History, color: "bg-red-500" },
                    { label: "Expiring Soon", value: stats.expiringSoon, icon: Calendar, color: "bg-purple-500" },
                ].map((stat, i) => (
                    <div key={i} className="card-premium rounded-2xl p-5 flex items-center gap-4">
                        <div className={`w-12 h-12 rounded-xl ${stat.color} flex items-center justify-center shadow-lg`}>
                            <stat.icon className="h-6 w-6 text-white" />
                        </div>
                        <div>
                            <p className="text-sm text-gray-500 font-medium">{stat.label}</p>
                            <p className="text-2xl font-bold text-gray-900">{stat.value}</p>
                        </div>
                    </div>
                ))}
            </div>

            {/* Table Section */}
            <div className="card-premium rounded-2xl overflow-hidden">
                <div className="p-6 border-b border-gray-100 flex flex-col md:flex-row gap-4 justify-between">
                    <div className="relative flex-1 max-w-md">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                        <input
                            type="text"
                            placeholder="Find stock by name..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="h-12 w-full rounded-xl border border-gray-200 bg-white pl-12 pr-4 text-sm focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20"
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <button onClick={() => setFilter("all")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${filter === 'all' ? 'bg-purple-600 text-white shadow-md' : 'bg-gray-50 text-gray-600'}`}>All Stock</button>
                        <button onClick={() => setFilter("low")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${filter === 'low' ? 'bg-orange-600 text-white shadow-md' : 'bg-gray-50 text-gray-600'}`}>Low Stock</button>
                        <button onClick={() => setFilter("expiring")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${filter === 'expiring' ? 'bg-red-600 text-white shadow-md' : 'bg-gray-50 text-gray-600'}`}>Expiring</button>
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead className="bg-gray-50/50">
                            <tr>
                                <th className="text-left py-4 px-6 text-xs font-bold text-gray-500 uppercase tracking-wider">Medicine</th>
                                <th className="text-left py-4 px-6 text-xs font-bold text-gray-500 uppercase tracking-wider">Batches</th>
                                <th className="text-left py-4 px-6 text-xs font-bold text-gray-500 uppercase tracking-wider">Price (PKR)</th>
                                <th className="text-left py-4 px-6 text-xs font-bold text-gray-500 uppercase tracking-wider">Total Stock</th>
                                <th className="text-left py-4 px-6 text-xs font-bold text-gray-500 uppercase tracking-wider">Status</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {filteredItems.map((item) => (
                                <tr key={item.id} className="hover:bg-gray-50/50 transition-colors">
                                    <td className="py-4 px-6">
                                        <div>
                                            <p className="font-bold text-gray-900">{item.name}</p>
                                            <p className="text-xs text-gray-500">{item.category}</p>
                                        </div>
                                    </td>
                                    <td className="py-4 px-6">
                                        <div className="flex flex-wrap gap-1">
                                            {item.batches.map((b: any) => (
                                                <span key={b.id} className="inline-block px-2 py-0.5 rounded bg-blue-50 text-[10px] font-bold text-blue-700">
                                                    {b.batchNo}
                                                </span>
                                            ))}
                                        </div>
                                    </td>
                                    <td className="py-4 px-6 text-gray-600">PKR {item.salePrice}</td>
                                    <td className="py-4 px-6">
                                        <span className="font-bold text-gray-900">{item.stock}</span>
                                    </td>
                                    <td className="py-4 px-6">
                                        <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold ${item.stock > 100 ? 'bg-green-100 text-green-700' :
                                            item.stock > 0 ? 'bg-orange-100 text-orange-700' : 'bg-red-100 text-red-700'
                                            }`}>
                                            <div className={`w-1.5 h-1.5 rounded-full ${item.stock > 100 ? 'bg-green-600' :
                                                item.stock > 0 ? 'bg-orange-600' : 'bg-red-600'
                                                }`} />
                                            {item.stock > 100 ? 'Comfortable' : item.stock > 0 ? 'Low Stock' : 'Out Stock'}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}
